-- Read-only structural inventory. Does not return customer records or credentials.
select jsonb_build_object(
  'tables', (select jsonb_agg(jsonb_build_object('table', c.relname, 'rls', c.relrowsecurity, 'force_rls', c.relforcerowsecurity) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),
  'columns', (select jsonb_agg(jsonb_build_object('table', table_name, 'column', column_name, 'type', udt_name, 'nullable', is_nullable, 'default', column_default) order by table_name, ordinal_position) from information_schema.columns where table_schema='public'),
  'constraints', (select jsonb_agg(jsonb_build_object('table', c.relname, 'name', con.conname, 'definition', pg_get_constraintdef(con.oid)) order by c.relname, con.conname) from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
  'indexes', (select jsonb_agg(jsonb_build_object('table', tablename, 'name', indexname, 'definition', indexdef) order by tablename,indexname) from pg_indexes where schemaname='public'),
  'policies', (select jsonb_agg(jsonb_build_object('table', tablename, 'name', policyname, 'permissive', permissive, 'roles', roles, 'command', cmd, 'using', qual, 'check', with_check) order by tablename,policyname) from pg_policies where schemaname='public'),
  'functions', (select jsonb_agg(jsonb_build_object('name', p.proname, 'args', pg_get_function_identity_arguments(p.oid), 'definition', pg_get_functiondef(p.oid)) order by p.proname, pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
  'triggers', (select jsonb_agg(jsonb_build_object('schema', n.nspname, 'table', c.relname, 'name', t.tgname, 'definition', pg_get_triggerdef(t.oid)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname='public' or (n.nspname='auth' and t.tgfoid in (select p.oid from pg_proc p join pg_namespace pn on pn.oid=p.pronamespace where pn.nspname='public')))),
  'extensions', (select jsonb_agg(jsonb_build_object('name', e.extname, 'schema', n.nspname) order by e.extname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace)
) as inventory;
